import SwiftUI\n\n// MARK: - Color Extensions\nextension Color {\n    static let casinoDark = Color(red: 0.1, green: 0.1, blue: 0.12)\n    static let casinoGold = Color(red: 1, green: 0.84, blue: 0)\n    static let casinoGreen = Color(red: 0.2, green: 0.84, blue: 0.4)\n    static let casinoRed = Color(red: 0.9, green: 0.2, blue: 0.2)\n}\n\n// MARK: - View Extensions\nextension View {\n    func glow(radius: CGFloat = 10, color: Color = .yellow) -> some View {\n        self\n            .shadow(color: color.opacity(0.5), radius: radius)\n    }\n    \n    func cardStyle() -> some View {\n        self\n            .padding()\n            .background(Color.black.opacity(0.3))\n            .cornerRadius(12)\n            .overlay(\n                RoundedRectangle(cornerRadius: 12)\n                    .stroke(Color.white.opacity(0.2), lineWidth: 1)\n            )\n    }\n}\n\n// MARK: - Double Extensions\nextension Double {\n    func asCurrency() -> String {\n        let formatter = NumberFormatter()\n        formatter.numberStyle = .currency\n        formatter.currencyCode = \"USD\"\n        return formatter.string(from: NSNumber(value: self)) ?? \"$0.00\"\n    }\n    \n    func asPercentage() -> String {\n        return String(format: \"%.1f%%\", self * 100)\n    }\n}\n\n// MARK: - Date Extensions\nextension Date {\n    func timeAgoDisplay() -> String {\n        let formatter = RelativeDateTimeFormatter()\n        formatter.unitsStyle = .abbreviated\n        return formatter.localizedString(for: self, relativeTo: Date())\n    }\n    \n    func isToday() -> Bool {\n        Calendar.current.isDateInToday(self)\n    }\n    \n    func isYesterday() -> Bool {\n        Calendar.current.isDateInYesterday(self)\n    }\n    \n    func isThisWeek() -> Bool {\n        let now = Date()\n        let calendar = Calendar.current\n        return calendar.dateComponents([.weekOfYear], from: self).weekOfYear == calendar.dateComponents([.weekOfYear], from: now).weekOfYear\n    }\n}\n\n// MARK: - Array Extensions\nextension Array where Element: Identifiable {\n    subscript(id: Element.ID) -> Element? {\n        get {\n            first { $0.id == id }\n        }\n    }\n}\n\n// MARK: - String Extensions\nextension String {\n    var isValidEmail: Bool {\n        let emailRegex = \"[A-Z0-9a-z._%+-]+@[A-Za-z0-9.-]+\\\\.[A-Za-z]{2,}\"\n        return NSPredicate(format: \"SELF MATCHES %@\", emailRegex).evaluate(with: self)\n    }\n    \n    var isValidUsername: Bool {\n        return self.count >= 3 && self.count <= 20 && !self.contains(\" \")\n    }\n    \n    var isStrongPassword: Bool {\n        let minLength = 8\n        let hasUpperCase = range(of: \"[A-Z]\", options: .regularExpression) != nil\n        let hasLowerCase = range(of: \"[a-z]\", options: .regularExpression) != nil\n        let hasDigits = range(of: \"[0-9]\", options: .regularExpression) != nil\n        \n        return self.count >= minLength && hasUpperCase && hasLowerCase && hasDigits\n    }\n}\n